function world(w, h, g) {
  const sky = X.createLinearGradient(0, 0, 0, g);
  sky.addColorStop(0, '#bde9ff');
  sky.addColorStop(1, '#f9f1c3');
  X.fillStyle = sky;
  X.fillRect(0, 0, w, g);
  X.fillStyle = '#d9f2a7';
  X.beginPath();
  X.moveTo(0, g - 90);
  for (let x = 0; x <= w; x += 70) {
    X.quadraticCurveTo(x + 35, g - 125 + (x % 140 ? 16 : 0), x + 70, g - 90);
    X.lineTo(w, g);
    X.lineTo(0, g);
    X.fill();
  }
  X.fillStyle = '#caa36a';
  X.fillRect(0, g, w, h - g);
  X.fillStyle = '#b48a56';
  for (let x = 0; x < w; x += 42) {
    X.fillRect(x, g + 18 + (x % 84 ? 7 : 0), 24, 5);
  }
  base(42, g - 22, 'ally');
  base(w - 42, g - 22, 'enemy');
}
